import re
import sys
from collections import Counter
from urllib.parse import urlparse

def count_domains(file_path):
    with open(file_path, 'r') as file:
        content = file.read()
    # Find all matches of http/https URLs in the text
    matches = re.findall(r'https?://[\w.-]+(?:/[\w./?=&%+-]*)?', content)
    hostnames = [urlparse(link).netloc for link in matches]
    return Counter(hostnames)

if __name__ == '__main__':
    if len(sys.argv) > 1:
        domain_counts = count_domains(sys.argv[1])
        for domain, count in domain_counts.items():
            print(f"{domain}: {count}")
    else:
        print("Please provide a filename as an argument.")
